/**
 * Interface icons from game-icons.net (by Lorc, Delapouite and contributors, CC BY 3.0).
 * They are single-colour SVGs filled with `currentColor`, so an icon takes the
 * text colour of wherever it sits and scales with the font size (1em square).
 * The set we use is generated by scripts/icons.mjs.
 */
import { ICON_BODIES } from './icons.data';
import type { Slot } from '../game/items';

export type IconName = keyof typeof ICON_BODIES;

/** An icon as HTML, for template strings. */
export const gi = (name: IconName, cls = '') => `<svg class="gi ${cls}" viewBox="0 0 512 512" aria-hidden="true">${ICON_BODIES[name]}</svg>`;

/** An icon as an element. */
export function giEl(name: IconName, cls = ''): SVGSVGElement {
  const t = document.createElement('template'); t.innerHTML = gi(name, cls);
  return t.content.firstChild as SVGSVGElement;
}

/** One clear silhouette per gear slot: the Bag's filter tabs and empty slots around the hero. */
export const SLOT_ICON: Record<Slot, IconName> = {
  weapon: 'broadsword', helmet: 'visored-helm', armor: 'breastplate', gloves: 'gauntlet',
  pants: 'trousers', boots: 'leather-boot', free: 'cape',
};
